/**
 * @method
 * @name scwin.tx_fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/disclosure/disclosurebyetn.do",
        ref: "dma_fnDownloadReq",
        target: "dlt_disclosureByStockType=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst00406.tx_fnDownload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
