    $("tr:even").addClass("active");
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() == null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() == null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은  3년 이내만 가능합니다.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDisclosureByStockTypeEtnSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "disclosurebystocktype_etn_down");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.listIdxSecuFind
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd
 * @returns
 * @hidden N
*/
scwin.listIdxSecuFind = function (isurCd) {
    /* sdd-asis-lifecycle:begin listIdxSecuFind — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/disclosure/listidxsecudetailed.do?method=readListIdxSecuDetailedMain";
    const wTitle = "";
    const wWidth = 870;
    const wHeight = 920;
    const wSco = "yes";
    const wUrl = url + "&isurCd=" + isurCd;
    $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof wTitle !== 'undefined' ? wTitle : '') ? Object.assign({ width: "", height: "", scrollbars: false, resizable: false, type: "pageFramePopup" }, { id: (typeof wTitle !== 'undefined' ? wTitle : '') }) : { width: "", height: "", scrollbars: false, resizable: false, type: "pageFramePopup" }), {});
    /* sdd-asis-lifecycle:end */
};


