 * @name scwin.setEtnInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isuSrtCd isuKorAbbrv isuCd
 * @returns
 * @hidden N
*/
scwin.setEtnInfo = function (isuSrtCd, isuKorAbbrv, isuCd) {
    /* sdd-asis-lifecycle:begin setEtnInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_etnIsuSrtNm').setValue(isuSrtCd);
    $c.util.getComponent('ipt_etnIsuSrtCd').setValue(isuSrtCd);
    /* sdd-asis-lifecycle:end */
};


function selCndt(val) {
    /* sdd-asis-lifecycle:begin selCndt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (val === 'N') {
        $("select[name=earyRedmptCycleCd]").attr("disabled", true);
    } else {
        $("select[name=earyRedmptCycleCd]").attr("disabled", false);
    }
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.selChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.selChange = function (val) {
    /* sdd-asis-lifecycle:begin selChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let sel = "";
    for (let i = 0; i < (function(){ throw 'unresolved:list:typeList'; })(); i++) {
        sel += "<option value='${typeList[__i].cdVal}'>${typeList[__i].cdValNm}</option>";
    }
    if (val === '4') {
        let str = "<font color='#295890'><b>조기상환조건 여부</b></font> &nbsp;<select id='earyRedmptCondYn' name='earyRedmptCondYn' onChange='selCndt(this.value)'><option value='Y'>예</option><option value='N'>아니오</option></select>&nbsp;&nbsp;";
        str += "<font color='#295890'><b>조기상환조건 주기</b></font> <select name='earyRedmptCycleCd' id='earyRedmptCycleCd'><option value=''>전체</option>" + sel + "</select>";
        (($c.util.getComponent('txt_viewCondition')) && ($c.util.getComponent('txt_viewCondition')).setValue ? ($c.util.getComponent('txt_viewCondition')).setValue(str) : (($c.util.getComponent('txt_viewCondition')) && ($c.util.getComponent('txt_viewCondition')).setText ? ($c.util.getComponent('txt_viewCondition')).setText(str) : void (str)));
    } else {
        $("#txt_viewCondition").children().remove();
        $c.util.getComponent('txt_viewCondition').setLabel("");
    }
    /* sdd-asis-lifecycle:end */
};
